import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as t,c as s,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.8.2","description":"Bug fix: multi-page searches no longer abort when GitHub rate-limits mid-pagination — the CLI now waits and resumes automatically.","frontmatter":{"title":"What's new in v1.8.2","description":"Bug fix: multi-page searches no longer abort when GitHub rate-limits mid-pagination — the CLI now waits and resumes automatically.","date":"2026-03-09T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-8-2.md","filePath":"blog/release-v1-8-2.md"}`),r={name:"blog/release-v1-8-2.md"};function o(n,e,l,h,c,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="what-s-new-in-github-code-search-v1-8-2" tabindex="-1">What&#39;s new in github-code-search v1.8.2 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-8-2" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.8.2&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.2" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.8.2</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="fix-multi-page-searches-aborted-by-rate-limits-now-auto-resume" tabindex="-1">Fix: multi-page searches aborted by rate limits now auto-resume <a class="header-anchor" href="#fix-multi-page-searches-aborted-by-rate-limits-now-auto-resume" aria-label="Permalink to &quot;Fix: multi-page searches aborted by rate limits now auto-resume&quot;">​</a></h3><p>When searching across a large organisation with many results (close to the GitHub 1 000-result cap), the CLI could crash mid-way through pagination with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>  Fetching results from GitHub… ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓░░  page 9/10</span></span>
<span class="line"><span>error: GitHub API rate limit exceeded. Please retry in 53 seconds.</span></span></code></pre></div><p>The search was lost at ~90 % completion and had to be restarted from scratch.</p><h4 id="root-causes-three-compounding-issues" tabindex="-1">Root causes (three compounding issues) <a class="header-anchor" href="#root-causes-three-compounding-issues" aria-label="Permalink to &quot;Root causes (three compounding issues)&quot;">​</a></h4><p><strong>1. Long rate-limit waits threw immediately.</strong><br> When <code>x-ratelimit-reset</code> indicated a wait longer than 10 seconds, <code>fetchWithRetry</code> threw an error instead of waiting. The pagination loop propagated this exception and discarded all pages already fetched.</p><p><strong>2. Secondary rate limits were not recognised.</strong><br> GitHub secondary rate limits return <code>403 + Retry-After</code> (without <code>x-ratelimit-remaining: 0</code>). This pattern bypassed the retry logic entirely and surfaced as an unhandled API error.</p><p><strong>3. 422 error when results hit exactly 1 000.</strong><br> When <code>total_count</code> was an exact multiple of 100 (e.g. 1 000 results across 10 full pages), the pagination loop attempted a page 11. GitHub rejects this with <code>422 Cannot access beyond the first 1000 results</code>.</p><h4 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h4><ul><li><p><strong>Auto-wait with visible feedback.</strong> When a rate-limit response is received during pagination, the CLI now prints a message, waits for the exact duration indicated by GitHub (<code>x-ratelimit-reset</code> or <code>Retry-After</code> + 1 s clock-skew buffer), and resumes automatically — no retry counting, no data lost:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>  Fetching results from GitHub… ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓░░  page 9/10</span></span>
<span class="line"><span>  Rate limited — waiting 53 seconds, resuming automatically…</span></span>
<span class="line"><span>  Fetching results from GitHub… ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓  page 10/10</span></span></code></pre></div></li><li><p><strong>Secondary rate limit detection.</strong> Any <code>403 + Retry-After</code> response is now treated as a retriable rate-limit condition.</p></li><li><p><strong>Page 11 guard.</strong> <code>fetchAllResults</code> now short-circuits before requesting a page beyond <code>totalPages</code>, preventing the 422 error at the cap.</p></li></ul><p><strong>Before:</strong> error at page 9, search lost.<br><strong>After:</strong> transparent pause, TUI opens with all 1 000 results.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or download the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.2" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>`,18)])])}const w=a(r,[["render",o]]);export{f as __pageData,w as default};
